[CmdletBinding()]
param()

$ErrorActionPreference = "Stop"
$repoRoot = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot ".."))
$pluginRoot = Join-Path $repoRoot "src\Rupture"
$architectureContract = Get-Content -LiteralPath (Join-Path $repoRoot "docs\RPT-External-PhysX-Architecture.md") -Raw
$readme = Get-Content -LiteralPath (Join-Path $repoRoot "README.md") -Raw

function Read-Source([string] $relativePath) {
    return Get-Content -LiteralPath (Join-Path $pluginRoot $relativePath) -Raw
}

function Assert-True([bool] $condition, [string] $message) {
    if (-not $condition) {
        throw "FAIL: $message"
    }

    Write-Output "PASS: $message"
}

$compiledSources = @(Get-ChildItem -LiteralPath $pluginRoot -Recurse -Filter "*.cs" | Where-Object {
    $_.FullName -notmatch '[\\/]RootMotion[\\/]'
})
$linkedLimbSources = @(
    (Join-Path $repoRoot "unity\RuptureWound\Assets\Rupture\Limbs\LimbSeverLevel.cs")
    (Join-Path $repoRoot "unity\RuptureWound\Assets\Rupture\Limbs\ProceduralLimbWoundGeometry.cs")
)
$allSource = (@($compiledSources | ForEach-Object { Get-Content -LiteralPath $_.FullName -Raw }) +
    @($linkedLimbSources | ForEach-Object { Get-Content -LiteralPath $_ -Raw })) -join "`n"

$entry = Read-Source "RupturePlugin.cs"
$entry += Read-Source "RuptureConfiguration.cs"
$lateUpdate = [regex]::Match($entry, '(?s)\tprivate void LateUpdate\(\).*?(?=\r?\n\tprivate )').Value
$killPatch = Read-Source "Combined\Patches\KillPatch.cs"
$impact = Read-Source 'Impacts\ImpactStateService.cs'
$coordinator = Read-Source "Ragdolls\Classes\RagdollCoordinator.cs"
$poseAssembly = Read-Source "Ragdolls/Classes/PendingPoseSnapshotAssembly.cs"
$limbDismemberment = Read-Source "Dismemberment\Classes\Limbs\LimbDismembermentSystem.cs"
$limbDismemberment += Read-Source "Dismemberment/Classes/Limbs/LimbDismembermentSystem.Worker.cs"
$limbDismemberment += Read-Source "Dismemberment/Classes/Limbs/LimbDismembermentSystem.Decals.cs"
$limbDismemberment += Read-Source "Dismemberment\Classes\Limbs\LimbCutLifetime.cs"
$sleepPolicy = Read-Source "Ragdolls\Classes\CorpseSleepPolicy.cs"
$sequencePolicy = Read-Source "Ragdolls\Classes\RagdollSequencePolicy.cs"
$ragdollPatch = Read-Source "Ragdolls\Patches\RagdollClassPatch.cs"
$ragdollWakePatch = Read-Source "Ragdolls\Patches\RagdollWakePatch.cs"
$weaponCollisionPatch = Read-Source "Ragdolls\Patches\CorpseWeaponCollisionPatch.cs"
$weaponCollisionFilter = Read-Source "Ragdolls\Classes\CorpseWeaponCollisionFilter.cs"
$physicsDiagnostics = Read-Source "Ragdolls\Classes\RagdollPhysicsDiagnostics.cs"
$physicsCensus = Read-Source "Ragdolls\Classes\PhysicsSceneCensus.cs"
$physicsSampler = Read-Source "Ragdolls\Classes\PhysicsCounterSampler.cs"
$physicsDiagnosticSource = $physicsDiagnostics + "`n" + $physicsCensus + "`n" + $physicsSampler
$corpseSleepPatch = Read-Source "Ragdolls\Patches\CorpseSleepPatch.cs"
$observedCorpseSleepPatch = Read-Source "Ragdolls\Patches\ObservedCorpseSleepPatch.cs"
$shotProcessor = Read-Source "Ragdolls\Classes\ShotImpactProcessor.cs"
$bodyImpulse = Read-Source "Ragdolls\Patches\BodiesImpulsePatch.cs"
$grenadePhysics = Read-Source "Ragdolls\Classes\GrenadePhysics.cs"
$shadowWorld = Read-Source "Ragdolls\Classes\ShadowRagdollWorld.cs"
$shadowWorld += Get-Content -LiteralPath (Join-Path $pluginRoot "Ragdolls/Classes/SimulationStepPolicy.cs") -Raw
$meshGeometry = Get-Content -LiteralPath (Join-Path $repoRoot "src\Rupture.PhysXBackend\MeshGeometry.cs") -Raw
$externalRuntime = Get-Content -LiteralPath (Join-Path $repoRoot "src\Rupture.PhysXBackend\ExternalPhysXRuntime.cs") -Raw
$externalHierarchy = Get-Content -LiteralPath (Join-Path $repoRoot "src\Rupture.PhysXBackend\EnvironmentHierarchyFilter.cs") -Raw
$externalRuntime += Get-Content -LiteralPath (Join-Path $repoRoot "src/Rupture.PhysXBackend/ExternalPhysicsHandles.cs") -Raw
$visiblePosePlayerLoop = Read-Source "Ragdolls\Classes\ShadowVisiblePosePlayerLoop.cs"
$wakePacket = Get-Content -LiteralPath (Join-Path $repoRoot "src/Rupture.Fika/Ragdolls/Classes/Packets/RagdollWakePacket.cs") -Raw
$poseSnapshotPacket = Read-Source "Ragdolls\Classes\Packets\RagdollPoseSnapshotPacket.cs"
$settlePacket = Read-Source "Ragdolls\Classes\Packets\RagdollSettlePacket.cs"
$rigidbodyForcePatches = Read-Source "Ragdolls\Patches\RigidbodyForcePatches.cs"
$helmetPatch = Read-Source "Ragdolls\Patches\HelmetThrowPhysicsPatch.cs"
$bloodStreamSystem = Read-Source "Dismemberment\Classes\BloodStreams\PulsatingBloodStreamSystem.cs"
$bloodStreamSystem += Read-Source "Dismemberment/Classes/BloodStreams/PulsatingBloodStreamSystem.Rendering.cs"

Assert-True (([regex]::Matches($allSource, 'new\s+KillPatch\s*\(\s*\)\s*\.Enable\s*\(')).Count -eq 1) "KillPatch is registered exactly once"
Assert-True ($killPatch -match 'ImpactStateService.Death' -and $killPatch -match 'RegisterDeath' -and $impact -match 'DeathApplied') "every authoritative first lethal transition enters the coordinator once"
Assert-True ($coordinator -match 'ObservedAliveAfterDeath' -and $coordinator -match 'isFirstLethalTransition\s*=\s*false') "duplicate lethal callbacks and revived deaths are distinguished"
Assert-True ($entry -notmatch 'Application\.OpenURL|Application\.Quit') "plugin does not terminate Tarkov"

$obsoleteNames = @(
    'Infinite Shell Casing Lifetime', 'Item Physics', 'Item Force Intensity', 'Use Active Ragdolls',
    'Player Body Collision', 'PuppetMaster', 'AnimationSeed', 'RagdollSyncPacket',
    'PlayerInitPatch\s*\(\)\.Enable', 'PhysicalItemsPatch\s*\(\)\.Enable', 'GrenadeItemsPatch\s*\(\)\.Enable',
    'ShellCasingPatch\s*\(\)\.Enable', 'LimbKillPatch\s*\(\)\.Enable'
)
foreach ($obsoleteName in $obsoleteNames) {
    Assert-True ($allSource -notmatch $obsoleteName) "obsolete feature is absent: $obsoleteName"
}
Assert-True (-not (Test-Path -LiteralPath (Join-Path $pluginRoot "Ragdolls\Classes\RootMotion"))) "RootMotion/PuppetMaster source is removed"
Assert-True ($allSource -notmatch 'AttachWeaponPatch\s*\(\)\.Enable|CreateCorpsePatch\s*\(\)\.Enable') "RPT observes the exact EFT weapon attachment and corpse-collider lifecycle instead of replacing either method"
Assert-True ($weaponCollisionPatch -match 'AttachWeapon' -and $weaponCollisionPatch -match '\[PatchPostfix\]' -and $weaponCollisionPatch -notmatch '\[PatchPrefix\]|return\s+false') "weapon collision filtering only observes EFT attachment through a postfix"
Assert-True ($weaponCollisionPatch -match 'typeof\(PlayerBones\)' -and $weaponCollisionPatch -match 'typeof\(TransformLinks\)') "weapon collision filtering targets the exact six-parameter EFT ABI"
Assert-True ($weaponCollisionPatch -match 'ShadowRagdollWorld\.AttachLateWeapon' -and $shadowWorld -match 'Late native weapon joined shadow physics independently') "late native weapon attachment is transactionally incorporated without an arbitrary frame delay"
Assert-True ($shadowWorld -match 'DetachWeaponFromCorpse\(rig\)' -and $shadowWorld -match 'DestroyObject\(nativeJoint\)' -and $shadowWorld -notmatch 'TryCopyWeaponJoint|ProxyWeaponJoint|SyncWeaponJointState') "shadow weapons are independent bodies with no cloned or polled corpse-hand joint"
Assert-True ($shadowWorld -match 'CorpseWeaponCollisionFilter\.Restore' -and $weaponCollisionFilter -match 'Physics\.IgnoreCollision\(corpseCollider, weaponCollider, ignore:\s*false\)' -and $shadowWorld -match 'ReferenceEquals\(leftBody, rig\.WeaponBody\)') "released shadow weapons retain weapon-to-corpse collision"
Assert-True ($weaponCollisionFilter -match 'Physics\.IgnoreCollision' -and $weaponCollisionFilter -match 'attachedRigidbody\s*!=\s*body' -and $weaponCollisionFilter -notmatch 'IgnoreLayerCollision|Object\.Destroy|_weaponJoint\s*=') "only corpse-to-own-weapon collider pairs are suppressed"
Assert-True ($weaponCollisionFilter -match 'PendingWeapons' -and $weaponCollisionFilter -match 'CompleteAfterRagdollStart' -and $coordinator -match 'CorpseWeaponCollisionFilter\.Reset\(\)') "weapon collision pairing tolerates native attach/start ordering and clears at raid boundaries"
Assert-True ($entry -match 'Native ragdoll weapon attachment ABI is unavailable[\s\S]{0,180}was not installed') "missing weapon attachment ABI fails open to EFT"
Assert-True ($shadowWorld -match 'SubmitStep\(deltaTime' -and $shadowWorld -notmatch '_physicsScene\.Simulate|CreateSceneParameters\(LocalPhysicsMode\.Physics3D\)' -and $entry -notmatch '"Shadow Physics Backend"') "shadow ragdolls use only standalone PhysX and never step a Unity shadow PhysicsScene"
Assert-True ($shadowWorld -match 'body\.Proxy\.angularVelocity\s*=\s*body\.NativeAngularVelocity;\s*body\.Proxy\.WakeUp\(\);' -and $shadowWorld -match 'Shadow ragdoll dormant') "new zero-velocity shadows are explicitly awakened and early dormancy is observable"
Assert-True ($shadowWorld -match 'UpdateController\.UnsupportRigidbody\(body\.Native\)' -and $shadowWorld -match 'body\.Native\.isKinematic\s*=\s*true' -and $shadowWorld -match 'NativeHandedOff') "a validated shadow transaction makes the native body a kinematic query shell and removes only its EFT support entry"
Assert-True ($shadowWorld -match 'AbortToNative' -and $shadowWorld -match 'UpdateController\.SupportRigidbody' -and $shadowWorld -match 'EFT native physics remains active') "shadow construction and runtime failures restore or preserve native EFT physics"
Assert-True ($shadowWorld -match 'retained \{rig\.CoreBodies\.Count\} kinematic corpse bodies' -and $shadowWorld -match 'rig\.Settled\s*=\s*true' -and $shadowWorld -notmatch 'DestroyObject\(body\.Proxy\?\.gameObject\)[\s\S]{0,160}rig\.Settled') "settled shadow corpse colliders remain in the shared scene without stopping the independent weapon"
Assert-True ($shadowWorld -match 'WakeDormantRigsFromExternalEnvironment' -and $externalRuntime -match 'RecentlyMovedBounds' -and $coordinator -match 'SendShadowWake') "moving external environment actors can authoritatively wake a dormant body before its hard deadline"
Assert-True ($externalRuntime -match '_movableEnvironmentActors' -and $externalRuntime -match '_environmentHierarchy.Allows\(collider.transform\)' -and $externalHierarchy -match 'type\s*==\s*"EFT\.Player"' -and $externalHierarchy -match 'type\s*==\s*"EFT\.Interactive\.Corpse"') "external environment maintenance tracks only movable actors and excludes living players and corpses"
Assert-True ($externalRuntime -match 'MaximumRetainedStaticEnvironment\s*=\s*2048' -and $externalRuntime -match '_retainedStaticEnvironment' -and $externalRuntime -match 'TrimRetainedStaticEnvironment' -and $externalRuntime -match 'SetEnvironmentActorEnabled\(actor,\s*false\)') "unused external static actors use a bounded disabled LRU cache"
Assert-True ($shadowWorld -match 'environmentCreated=' -and $shadowWorld -match 'environmentReused=' -and $shadowWorld -match 'bodyBuildMilliseconds' -and $shadowWorld -match 'jointBuildMilliseconds' -and $shadowWorld -match 'environmentBuildMilliseconds' -and $shadowWorld -match 'handoffMilliseconds') "shadow build logs expose phase timing and environment-cache reuse"
Assert-True ($shadowWorld -match 'SettledCollisionActivationRadius' -and $shadowWorld -match 'UpdateSettledCollisionActivation' -and $shadowWorld -match 'if\s*\(RagdollCoordinator\.ImpactReactivationEnabled\)' -and $shadowWorld -match 'bool enable\s*=\s*false' -and $shadowWorld -match 'lastSimPopulation=') "settled corpse collision is spatially culled unless permanent impact reactivation selects the equivalent fast path"
Assert-True ($shadowWorld -match 'ConfigureCorpseCollision' -and $shadowWorld -match 'collider\.gameObject\.layer\s*=\s*deadbodyLayer' -and $shadowWorld -match 'collider\.includeLayers\s*=.*deadbodyMask' -and $shadowWorld -match 'collider\.excludeLayers\s*=.*~deadbodyMask') "physics-only corpse colliders explicitly permit Deadbody-to-Deadbody contact without changing the global matrix"
Assert-True ($shadowWorld -match 'centerBody\.Proxy\.TransformPoint\(centerBody\.Proxy\.centerOfMass\)' -and $shadowWorld -match 'ProximityEnvironmentRefreshIntervalFrames\s*=\s*4' -and $shadowWorld -match 'MaximumProximityAcquiresPerFrame\s*=\s*2' -and $shadowWorld -match '_environmentRefreshCursor') "proximity maintenance uses one representative cached body and distributes dense refreshes fairly across frames"
Assert-True ($entry -match '"Wake Corpses On Impact",\s*true' -and $entry -match 'another bounded Ragdoll Sleep Time') "post-mortem corpse reactivation is explicit and enabled by default"
Assert-True ($entry -match '"Killshot Stream Duration \(Seconds\)",\s*6f' -and $entry -match '"Dismemberment Stream Duration \(Seconds\)",\s*10f') "pulsating killshot and dismemberment defaults are bounded to six and ten seconds"
Assert-True ($bloodStreamSystem -match 'Physics\.Raycast\(' -and $bloodStreamSystem -match 'MaximumVisualEmitters\s*=\s*64' -and $bloodStreamSystem -match 'MaximumRenderedEmitters\s*=\s*24' -and $bloodStreamSystem -match 'MaximumStreamSamplesPerEmitter\s*=\s*96') "blood streams use bounded analytical trajectory prediction without particle collision callbacks"
Assert-True ($shadowWorld -match 'WakeFromImpact' -and $shadowWorld -match 'AreNativeCollidersTouching' -and $shadowWorld -match 'ImpactWakeQueue' -and $shadowWorld -match 'leftBounds\.Expand\(0\.1f\)') "impact wake propagation follows a bounded transitive chain of touching corpse colliders"
Assert-True ($shadowWorld -match 'TryAcquireEnvironment\(rig, center, sweepEnd' -and $shadowWorld -match 'rig\.IgnoreNativeStopped\s*=\s*true' -and $shadowWorld -match 'rig\.StartedAt\s*=\s*Time\.realtimeSinceStartup') "a settled shadow reacquires local environment and ignores the already-completed native stop only for its new bounded cycle"
Assert-True ($coordinator -match 'ParkState\(RagdollState state\)' -and $coordinator -match 'ActiveStates\.Remove\(state\)' -and $coordinator -match 'ShouldParkState') "reactivable settled identities remain addressable without returning to the per-frame active collection"
Assert-True ($coordinator -match 'GetStateForCorpse\(corpse, allowRetired:\s*ImpactReactivationEnabled\)' -and $coordinator -match 'ReactivateFromMovingEnvironment' -and $shadowWorld -match 'RagdollCoordinator\.ReactivateFromMovingEnvironment') "old tombstoned corpses and settled bodies contacted by moving environment remain wakeable"
Assert-True ($entry -match 'ShadowVisiblePosePlayerLoop\.EnsureInstalled\(\)' -and $entry -match 'ShadowVisiblePosePlayerLoop\.Remove\(\)' -and $entry -match 'private void LateUpdate\(\)[\s\S]{0,450}ShadowRagdollWorld\.LateUpdate\([^\r\n]+[\s\S]{0,650}ShadowRagdollWorld\.LateUpdateVisibleShell\(\)') "LateUpdate always writes the simulated pose to the rendered native shell before skinning"
Assert-True ($visiblePosePlayerLoop -match 'PostLateUpdate\.EndGraphicsJobsAfterScriptLateUpdate' -and $visiblePosePlayerLoop -match 'RagdollCoordinator\.IsRemoteClient' -and $visiblePosePlayerLoop -match 'HasExecuted' -and $visiblePosePlayerLoop -notmatch '\.Simulate\(') "remote Fika clients receive an observable second presentation pass without another physics step"
Assert-True ($entry -match 'raidWorldActive\s*&&\s*!_wasInRaid[\s\S]{0,180}ShadowVisiblePosePlayerLoop\.EnsureInstalled' -and $visiblePosePlayerLoop -match 'ContainsPass') "raid-world entry repairs a presentation pass replaced by another plugin PlayerLoop"
Assert-True ($shadowWorld -match 'LateUpdateVisibleShell' -and $shadowWorld -match 'visible\.SetPositionAndRotation\(targetPosition, targetRotation\)' -and $shadowWorld -match 'latePoseCorrectionFrames=' -and $shadowWorld -match 'maxPoseChange=') "proxy movement and late visible-pose ownership are observable without per-frame logging"
Assert-True ($ragdollWakePatch -match 'nameof\(EFT.Interactive.CorpseRagdoll\.WakeUp\)' -and $ragdollWakePatch -match '\[PatchPostfix\]' -and $shadowWorld -match 'WakeFromNative') "native EFT/Fika wake requests are forwarded into dormant shadow rigs"
Assert-True ($entry -match 'RegisterCommand\("RPTPhysicsStatus",\s*RagdollPhysicsDiagnostics\.LogStatus\)' -and $physicsDiagnostics -match 'UpdateController\._rigidbodies' -and $physicsDiagnostics -match 'Simulation\.UpdateMode') "read-only physics diagnostics expose simulation mode and supported-body counts"
Assert-True ($entry -match 'RegisterCommand\("RPTPhysicsBodies",\s*RagdollPhysicsDiagnostics\.LogSupportedBodies\)' -and $physicsDiagnostics -match 'GetHierarchyPath' -and $physicsDiagnostics -match 'GetOwnerTypes') "supported-body diagnostics expose identities, hierarchy and ownership"
Assert-True ($entry -match 'RegisterCommand\("RPTPhysicsScene",\s*RagdollPhysicsDiagnostics\.LogSceneCensus\)' -and $physicsCensus -match 'FindObjectsByType<Rigidbody>' -and $physicsCensus -match 'FindObjectsByType<Collider>' -and $physicsCensus -match 'defaultPhysicsScene') "one-shot census distinguishes the full default physics scene from EFT's support registry"
Assert-True ($physicsCensus -match 'awake dynamic body' -and $physicsCensus -match 'rigidbody\.IsSleeping\(\)[\s\S]{0,220}else[\s\S]{0,220}awakeBodies\.Add\(rigidbody\)' -and $physicsCensus -match 'velocity\.magnitude' -and $physicsCensus -match 'GetPrimaryOwnerType') "scene census identifies the awake dynamic bodies PhysX can actually integrate"
Assert-True ($entry -match 'RegisterCommand\("RPTPhysicsSample",\s*RagdollPhysicsDiagnostics\.ToggleCounterSample\)' -and $physicsSampler -match 'ProfilerRecorderHandle\.GetAvailable' -and $physicsSampler -match 'SampleDurationSeconds\s*=\s*30f') "bounded native physics-counter sampling is available"
Assert-True ($physicsSampler -match 'ProfilerRecorder\.StartNew' -and $physicsSampler -match 'Physics\.Simulate' -and $physicsSampler -match 'ScScene\.rigidBodySolver' -and $physicsSampler -match 'LogAvailableMarkers') "physics sampling probes installed native markers and diagnoses stripped release counters"
Assert-True ($physicsSampler -match 'MaximumGateTransitions\s*=\s*96' -and $physicsSampler -match 'enabledWithoutSupportedAwakeSeconds' -and $physicsSampler -match 'GetIgnoreLayerCollision' -and $physicsSampler -match 'GateTransitions') "one capture records bounded support-gate transitions and the Deadbody collision matrix"
Assert-True ($physicsSampler -match 'MaximumRecorders\s*=\s*192' -and $physicsSampler -match 'capacity:\s*1' -and $physicsSampler -match 'DisposeRecorders\(\)' -and $entry -match 'RagdollPhysicsDiagnostics\.Reset\(\)') "physics recorders have bounded capacity and are disposed at raid boundaries"
Assert-True ($physicsDiagnosticSource -notmatch 'Physics\.Simulate\s*\(|Physics\.SyncTransforms\s*\(|set_Update|set_Enabled|SupportRigidbody|UnsupportRigidbody|isKinematic\s*=|Physics\.IgnoreCollision\s*\(|Physics\.IgnoreLayerCollision\s*\(') "physics diagnostics cannot mutate or drive EFT physics"

Assert-True ($ragdollPatch -match '\[PatchPostfix\]' -and $ragdollPatch -notmatch '\[PatchPrefix\]') "EFT.Interactive.CorpseRagdoll.Start is observed only through a postfix"
Assert-True ($ragdollPatch -notmatch 'return\s+false') "RPT never suppresses native EFT.Interactive.CorpseRagdoll.Start"
Assert-True ($corpseSleepPatch -match '\[PatchPostfix\]' -and $corpseSleepPatch -match 'ShouldStop\(__instance,\s*__result,\s*sleeping,\s*timePass\)') "corpse sleep augments EFT's native decision through a postfix"
Assert-True ($observedCorpseSleepPatch -match 'typeof\(ObservedCorpse\)' -and $observedCorpseSleepPatch -match 'BindingFlags\.DeclaredOnly' -and $observedCorpseSleepPatch -match '\[PatchPostfix\]' -and $observedCorpseSleepPatch -match 'ShouldStop\(__instance,\s*__result,\s*sleeping,\s*timePass\)') "Fika observed corpses receive the same bounded native sleep policy"
Assert-True ($coordinator -match 'shadowActive\s*\|\|\s*shadowSettled' -and $coordinator -match 'shouldStop\s*=\s*shadowSettled\s*\|\|\s*timedOut' -and $coordinator -match 'shouldStop\s*=\s*nativeResult\s*\|\|\s*nativeSleeping\s*\|\|\s*timedOut') "shadow lifecycle owns its sleep decision while a failed or disabled shadow retains native EFT sleep"
Assert-True ($coordinator -match 'retainNativeQueryShell\s*=\s*ImpactReactivationEnabled\s*&&\s*\(shadowActive\s*\|\|\s*shadowSettled\)' -and $coordinator -match 'return\s+retainNativeQueryShell\s*\?\s*false\s*:\s*shouldStop') "impact-reactivable external corpses settle without allowing EFT to retire their ballistic query shell"
Assert-True ($entry -match 'typeof\(ObservedCorpse\)\.GetMethod' -and $entry -match 'observedCorpseCheck\s*==\s*null' -and $entry -match 'new\s+ObservedCorpseSleepPatch\(\)\.Enable\(\)') "observed-corpse ABI is validated before lifecycle patches are installed"
Assert-True ($entry -match 'if\s*\(ragdollStart == null \|\| corpseCheck == null \|\| observedCorpseCheck == null\)\s*\{[^}]*Native ragdoll ABI targets are unavailable[^}]*ShadowRagdollWorld\.Disable\([^}]*return;') "missing native ABI targets fail open to EFT"
Assert-True ($sleepPolicy -match 'MinimumDurationSeconds\s*=\s*1' -and $sleepPolicy -match 'MaximumDurationSeconds\s*=\s*15') "ragdoll duration is bounded to 1-15 seconds"
Assert-True ($sleepPolicy -match 'NativeInitialDelaySeconds\s*=\s*1f') "sleep fallback accounts for EFT's confirmed initial one-second delay"
Assert-True ($entry -match '"Ragdoll Sleep Time",\s*5' -and $entry -match 'AcceptableValueRange<int>') "ragdoll sleep defaults to five seconds with a bounded config range"
Assert-True ($entry -match '"Localized Ragdoll Physics",\s*true' -and $entry -match 'RegisterCommand\("RPTShadowStatus"') "localized ragdolls are configurable and expose bounded live diagnostics"
Assert-True ($entry -match '"Continuously Simulate Shadow Scene",\s*false' -and $entry -match 'ShadowRagdollWorld\.Update\(raidWorldActive,\s*raidSimulationActive\)' -and $entry -match 'AbstractGame>\.Instance\.Status\s*!=\s*GameStatus\.Started') "continuous local-scene simulation is an opt-in started-raid debug mode"
Assert-True ($shadowWorld -match 'continuousSimulation\s*&&\s*!EnsureScene' -and $shadowWorld -match '!hasActiveRig\s*&&\s*!continuousSimulation' -and $shadowWorld -match 'timingBuckets=empty:') "debug stepping covers empty and passive scenes while recording population-specific timings"
Assert-True ($lateUpdate -match 'ShadowRagdollWorld\.LateUpdate\(raidSimulationActive\)' -and $shadowWorld -match 'internal static void LateUpdate\(bool inRaid\)[\s\S]{0,900}Simulate\(inRaid,\s*elapsed,\s*elapsed\)') "LateUpdate submits the graphical elapsed-time step (structural wiring check)"
Assert-True ($entry -notmatch 'AutoCycleShadowPhysicsStage|ShadowPhysicsPlayerLoop' -and $shadowWorld -notmatch 'ShadowPhysicsSimulationStage|AutoCycle|PostLateUpdate|SimulationStageAverage|SimulationStageSamples' -and -not (Test-Path -LiteralPath (Join-Path $pluginRoot 'Ragdolls\Classes\ShadowPhysicsPlayerLoop.cs'))) "alternate physics-simulation stages, selectors, cycling and PlayerLoop hooks are removed"
Assert-True ($shadowWorld -notmatch 'Simulate\(inRaid[^\r\n]*ShadowPhysics' -and ([regex]::Matches($shadowWorld, 'Simulate\(inRaid,').Count -eq 2) -and $shadowWorld -match 'MaximumStepRateInterval\s*=\s*1f\s*/\s*30f' -and $shadowWorld -match 'frameDeltaTime\s*>=\s*MaximumStepRateInterval[\s\S]{0,180}simulationDeltaTime\s*=\s*accumulator[\s\S]{0,100}accumulator\s*=\s*0f' -and $shadowWorld -match 'TryConsume\(Time\.deltaTime,\s*ref\s+_headlessSimulationAccumulator,\s*out\s+float\s+simulationDeltaTime\)' -and $shadowWorld -match 'Simulate\(inRaid,\s*simulationDeltaTime,\s*simulationDeltaTime\)') "headless simulation submits at most once per Update, caps faster authorities to 30 Hz, and carries the complete elapsed delta when Update falls below 30 Hz"
Assert-True ($entry -match '"Log Shadow Scene Status Every Second",\s*false' -and $entry -match '"Log Shadow Scene Performance Every Second",\s*false' -and $lateUpdate -match 'ShadowRagdollWorld\.LateUpdate\(raidSimulationActive\)[\s\S]*RecordPluginLateUpdate[\s\S]*ShadowRagdollWorld\.UpdateStatusLogging\(raidSimulationActive\)') "status and performance logging are independently opt-in, raid-restricted, and follow the live simulation callback"
Assert-True ($shadowWorld -match 'UpdateStatusLogging' -and $shadowWorld -match 'Stopwatch\.GetTimestamp\(\)' -and $shadowWorld -match '_nextStatusLogTimestamp\s*=\s*now\s*\+\s*Stopwatch\.Frequency' -and $shadowWorld -match 'LogStatus\(\);') "periodic status logging uses a monotonic real-time clock and skips catch-up bursts"
Assert-True ($shadowWorld -match 'nativeQueryShellColliders=' -and $shadowWorld -match 'GetNativeQueryShellCounts' -and $shadowWorld -match 'collider\.enabled\s*&&\s*collider\.gameObject\.activeInHierarchy') "status logging exposes whether retained Unity ballistic query colliders remain alive and enabled"
Assert-True ($entry -notmatch 'Log Generated Environment Colliders|Dump Generated Environment Colliders|DumpGeometryLookupManifest' -and -not (Test-Path -LiteralPath (Join-Path $pluginRoot 'Ragdolls\Classes\GeneratedEnvironmentColliderDumper.cs'))) "obsolete GPU collider feasibility diagnostics are removed"
Assert-True ($meshGeometry -notmatch 'AsyncGPUReadback|GraphicsBuffer|GetVertexBuffer|GetIndexBuffer' -and $externalRuntime -match 'UnityPhysXMeshGeometrySource') "production external mesh reconstruction exclusively reuses Unity-owned cooked PhysX geometry"
Assert-True ($externalRuntime -match 'External PhysX owner operation failed:\s*\{DescribeException\(work\.Exception\)\}' -and $externalRuntime -match 'current\.InnerException' -and $externalRuntime -match 'depth\s*<\s*8') "external owner-thread failures retain their bounded native exception chain in live logs"
Assert-True ($externalRuntime -match 'EnvironmentRadius\s*=\s*2f' -and $shadowWorld -match 'EnvironmentPredictionSeconds\s*=\s*0\.5f' -and $externalRuntime -match 'OverlapCapsuleNonAlloc') "external environment acquisition uses a two-metre velocity-predicted swept sphere"
Assert-True ($shadowWorld -match 'EnvironmentRefreshDistance\s*=\s*0\.5f' -and $shadowWorld -match 'EnvironmentSweepEnd' -and $shadowWorld -match '_externalRuntime\.ReleaseEnvironment\(rig\.ExternalGroup\)') "the active external environment corridor refreshes for movement or velocity changes and releases stale actors"

foreach ($packetType in @('RagdollStartPacket', 'RagdollPointImpulsePacket', 'RagdollRadialImpulsePacket', 'RagdollForcePacket', 'RagdollWakePacket', 'RagdollPoseSnapshotPacket', 'RagdollSettlePacket')) {
    Assert-True ((Get-Content -LiteralPath (Join-Path $repoRoot "src/Rupture.Fika/FikaRuntime.cs") -Raw) -match "RegisterPacket<$packetType>") "Fika registers $packetType"
}
Assert-True ((Get-Content -LiteralPath (Join-Path $repoRoot 'src/Rupture.Fika/FikaRuntime.cs') -Raw) -match 'DeliveryMethod\.ReliableOrdered') "ragdoll lifecycle packets use reliable ordered delivery"
Assert-True ($coordinator -match 'ReactivateSettled\s*=\s*1' -and $coordinator -match 'DynamicDuration\s*=\s*state\.DynamicDuration' -and $coordinator -match 'WakeFromNetwork' -and $wakePacket -match 'writer\.Put\(ReactivateSettled\)' -and $wakePacket -match 'writer\.Put\(DynamicDuration\)') "Fika transmits authoritative bounded corpse reactivation"
Assert-True ($coordinator -match 'PendingLifetimeSeconds\s*=\s*10f') "early Fika events expire after ten seconds"
Assert-True ($sequencePolicy -match 'receivedEvents\.Add' -and $sequencePolicy -match 'DeathSequenceRelation\.Current') "Fika lifecycle events are sequence-checked and deduplicated"
